CREATE OR REPLACE FUNCTION public.link_all_restaurants_systematically()
 RETURNS TABLE(restaurant_id uuid, restaurant_name text, updated_place_id text, method text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec RECORD;
  place_result RECORD;
  updated_count INTEGER := 0;
BEGIN
  -- Step 1: Link by exact name matches with existing restaurants that have place_ids
  FOR rec IN 
    SELECT r1.id, r1.name, r1.address, r1.city
    FROM public.restaurants r1
    WHERE r1.google_place_id IS NULL 
      AND r1.rating IS NOT NULL 
      AND r1.is_wishlist = false
  LOOP
    -- Try exact name match first
    SELECT r2.google_place_id INTO place_result
    FROM public.restaurants r2
    WHERE r2.google_place_id IS NOT NULL
      AND LOWER(TRIM(r2.name)) = LOWER(TRIM(rec.name))
      AND (
        LOWER(TRIM(r2.city)) = LOWER(TRIM(rec.city))
        OR LOWER(TRIM(r2.address)) LIKE '%' || LOWER(TRIM(SPLIT_PART(rec.address, ',', 1))) || '%'
      )
    LIMIT 1;

    IF place_result.google_place_id IS NOT NULL THEN
      UPDATE public.restaurants 
      SET google_place_id = place_result.google_place_id
      WHERE id = rec.id;

      updated_count := updated_count + 1;
      RETURN QUERY SELECT rec.id, rec.name, place_result.google_place_id, 'exact_name_match'::TEXT;
      CONTINUE;
    END IF;

    -- Try fuzzy name match with restaurants
    SELECT r2.google_place_id INTO place_result
    FROM public.restaurants r2
    WHERE r2.google_place_id IS NOT NULL
      AND (
        LOWER(TRIM(r2.name)) LIKE '%' || LOWER(TRIM(rec.name)) || '%'
        OR LOWER(TRIM(rec.name)) LIKE '%' || LOWER(TRIM(r2.name)) || '%'
        OR (LENGTH(rec.name) > 4 AND LENGTH(r2.name) > 4 AND 
            LOWER(SUBSTRING(r2.name, 1, 5)) = LOWER(SUBSTRING(rec.name, 1, 5)))
      )
      AND (
        LOWER(TRIM(r2.city)) = LOWER(TRIM(rec.city))
        OR LOWER(TRIM(r2.address)) LIKE '%' || LOWER(TRIM(SPLIT_PART(rec.address, ',', 1))) || '%'
      )
    LIMIT 1;

    IF place_result.google_place_id IS NOT NULL THEN
      UPDATE public.restaurants 
      SET google_place_id = place_result.google_place_id
      WHERE id = rec.id;

      updated_count := updated_count + 1;
      RETURN QUERY SELECT rec.id, rec.name, place_result.google_place_id, 'fuzzy_name_match'::TEXT;
      CONTINUE;
    END IF;

    -- Try to match with user_reviews table
    SELECT ur.restaurant_place_id INTO place_result
    FROM public.user_reviews ur
    WHERE ur.restaurant_place_id IS NOT NULL
      AND (
        LOWER(TRIM(ur.restaurant_name)) = LOWER(TRIM(rec.name))
        OR LOWER(TRIM(ur.restaurant_name)) LIKE '%' || LOWER(TRIM(rec.name)) || '%'
        OR LOWER(TRIM(rec.name)) LIKE '%' || LOWER(TRIM(ur.restaurant_name)) || '%'
        OR (LENGTH(rec.name) > 4 AND LENGTH(ur.restaurant_name) > 4 AND 
            LOWER(SUBSTRING(ur.restaurant_name, 1, 5)) = LOWER(SUBSTRING(rec.name, 1, 5)))
      )
    LIMIT 1;

    IF place_result.restaurant_place_id IS NOT NULL THEN
      UPDATE public.restaurants 
      SET google_place_id = place_result.restaurant_place_id
      WHERE id = rec.id;

      updated_count := updated_count + 1;
      RETURN QUERY SELECT rec.id, rec.name, place_result.restaurant_place_id, 'user_review_match'::TEXT;
    END IF;
  END LOOP;

  RAISE LOG 'Systematically linked % restaurants with Google Place IDs', updated_count;
END;
$function$
